import pandas as pd
import random
import re


def task_func(data_list, seed=None):
    """Apply a randomly selected operation to each comma-separated string."""
    random.seed(seed)
    rows = []
    for original in data_list:
        # A single space following a comma is treated as delimiter formatting;
        # any additional whitespace and all letter casing are retained.
        parts = re.split(r', ?', original)
        operation = random.choice(['remove', 'replace', 'shuffle', 'randomize'])

        if operation == 'remove':
            if len(parts) > 1:
                parts.remove(random.choice(parts))
        elif operation == 'replace':
            index = random.randrange(len(parts))
            parts[index] = 'random_string'
        elif operation == 'shuffle':
            random.shuffle(parts)
        else:
            parts = random.sample(parts, len(parts))

        rows.append((original, ', '.join(parts)))

    return pd.DataFrame(rows, columns=['Original String', 'Modified String'])

